            var snapshot = (JObject)DeepClone();
            foreach (var name in new[] { "number", "name", "category", "type", "type2", "description", "legacyNumber", "ownerUid", "dimensionName", "phase", "status", "priority", "risk", "riskDescription", "billable", "timeRecordable", "timeRecordType", "mail", "readPermissionProfiles", "readPermissionLogins", "writePermissionProfiles", "writePermissionLogins", "leadBudget", "leadAuthority", "leadNeed", "leadTime", "leadNotice", "interestedBudget", "interestedAuthority", "interestedNeed", "interestedTime", "salesKontaktType", "salesInternalOrganisation", "salesChannel", "salesCampaignName", "salesActivity", "salesPhase", "salesStatus", "salesPriority", "salesRisk", "salesDescription", "replacementProductName", "residualProductName", "competitionProductsName", "salesPotenzial", "servicePartnerName", "competitiveStrength" }) ValidateKind(snapshot[name], name, JTokenType.String, creating);
            foreach (var name in new[] { "estimatedHoursMode", "salesUpgrade" }) ValidateKind(snapshot[name], name, JTokenType.Boolean, creating);
            foreach (var name in new[] { "customFields", "projectEmployees" }) ValidateKind(snapshot[name], name, JTokenType.Array, creating);
            foreach (var name in new[] { "contactId", "initiatorContactId", "contactPerson", "startTs", "endTs", "decisionTs", "dimensionNumber", "hoursPerDay", "salesPersonId", "salesContractPerson", "leadPersonId", "reminderDate", "salesReminderFrom", "salesReminderTo", "contractObligation" }) ValidateInteger(snapshot[name], name, true, creating);
            foreach (var name in new[] { "workdays", "permissionType" }) ValidateInteger(snapshot[name], name, false, creating);
            foreach (var name in new[] { "estimatedHours", "leadBudgetSum", "interestedBudgetSum" }) ValidateNumber(snapshot[name], name, creating);
            if (creating && (snapshot["name"]?.Type != JTokenType.String || snapshot["contactId"]?.Type != JTokenType.Integer))
                throw new ArgumentException("A supplied sales-project creation object requires an explicit name and contactId.", "request");
            if (snapshot["customFields"] is JArray custom)
                foreach (var item in custom)
                    if (!(item is JObject row) || row["customFieldName"]?.Type != JTokenType.String || row.Property("customFieldValue") == null || (creating && row["customFieldValue"].Type == JTokenType.Null))
                        throw new ArgumentException("A custom field requires its original string name and explicit value.", "request");
            if (snapshot["projectEmployees"] is JArray employees)
                foreach (var item in employees)
                {
                    if (!(item is JObject row)) throw new ArgumentException("A project-team entry must be a JSON object.", "request");
                    new ProjectEmployeeWriteRequest(row).SnapshotForSend(creating);
                }
            return snapshot.ToString(Newtonsoft.Json.Formatting.None);
        }

        private static void ValidateKind(JToken value, string name, JTokenType kind, bool creating)
        {
            if (value == null || (!creating && value.Type == JTokenType.Null)) return;
            if (value.Type != kind) throw new ArgumentException("The " + name + " field has an incompatible JSON kind.", "request");
        }

        private static void ValidateInteger(JToken value, string name, bool wide, bool creating)
        {
            if (value == null || (!creating && value.Type == JTokenType.Null)) return;
            long number;
            if (value.Type != JTokenType.Integer || !long.TryParse(value.ToString(Newtonsoft.Json.Formatting.None), NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out number) ||
                (!wide && (number < int.MinValue || number > int.MaxValue)))
                throw new ArgumentException("The " + name + " field must be a JSON integer within its declared width.", "request");
        }
        private static void ValidateNumber(JToken value, string name, bool creating)
        {
            if (value == null || (!creating && value.Type == JTokenType.Null)) return;
            if (value.Type != JTokenType.Integer && value.Type != JTokenType.Float)
                throw new ArgumentException("The " + name + " field must be an original JSON number.", "request");
            var scalar = ((JValue)value).Value;
            if ((scalar is double number && (double.IsNaN(number) || double.IsInfinity(number))) ||
                (scalar is float single && (float.IsNaN(single) || float.IsInfinity(single))))
                throw new ArgumentException("The " + name + " field must be a finite JSON number.", "request");
        }
    }
